/** POST /api/v1/messages/receipts, by one of the recipient's own paired nodes (`node_id`, checked like `source_node_id`). One receipt is a batch of one; a node sends what it owes in batches of at most RECEIPT_BATCH_MAX. */
export interface ReceiptBatch {
  node_id: string;
  receipts: ReceiptItem[];
}

/** The facts after the batch, one per message the caller is the recipient of. `not_found` lists the rest: a message that does not exist, that the caller may not see, or that the caller sent (the sender's own read is no receipt). It is settled: the node stops owing it. */
export interface ReceiptBatchResult {
  facts: ReceiptFacts[];
  not_found: string[];
}

/** The recipient's facts about one message. `received_at` is the first durable local storage by any of the recipient's nodes, `read_at` the first time the owner had the body displayed. Each is set once, by the server's clock, and never moves; a read may arrive before a received and is kept (the received fact then stays unset until it comes). */
export interface ReceiptFacts {
  message_id: string;
  recipient_github_id: number;
  received_at: string | null;
  read_at: string | null;
  nodes: NodeReceipt[];
  revision: number;
}

/** One receipt. `read` only ever comes from the owner's GUI after the body was displayed (or an explicit mark-read), never from a notification, a summary or the model. */
export interface ReceiptItem {
  message_id: string;
  kind: "received" | "read";
}

/** GET /api/v1/messages/recipients: the existing team roster's active members, readable by every member's paired JARVIS (the roster route itself stays administrators' only). It includes the caller, who is shown as Me. Not a second directory: it is that roster, read. */
